import time

def construct():
    start_time = time.time()
    deadline = start_time + 50.0  # Safety margin
    
    N = 17
    MIN_DIST = 6
    
    # We will construct the [17, 8, 6] linear code.
    # This code is generated by h(x) = (x+1)m_3(x) in GF(2)[x] / (x^17 - 1).
    # m_3(x) is the minimal polynomial of alpha^3 over GF(2), where alpha is a primitive 17th root of unity in GF(2^8).
    
    # GF(2^8) arithmetic
    # Primitive polynomial: x^8 + x^4 + x^3 + x^2 + 1 (0x11d)
    
    def gf_mul(a, b):
        res = 0
        while b:
            if b & 1:
                res ^= a
            b >>= 1
            a <<= 1
            if a & 0x100:
                a ^= 0x11d
        return res

    def gf_pow(a, n):
        res = 1
        while n:
            if n & 1:
                res = gf_mul(res, a)
            a = gf_mul(a, a)
            n >>= 1
        return res

    # beta = 3 is a primitive element for GF(2^8) with 0x11d
    beta = 3
    alpha = gf_pow(beta, 15) # alpha^17 = 1
    
    # Find minimal polynomial of alpha^3
    a3 = gf_pow(alpha, 3)
    v = [1] * 9
    for i in range(1, 9):
        v[i] = gf_mul(v[i-1], a3)
        
    # Solve for coefficients c_0..c_7 of m_3(x) = x^8 + c_7 x^7 + ... + c_0
    # v[8] = sum c_i v[i]
    
    M = [[0]*8 for _ in range(8)]
    for i in range(8):
        for j in range(8):
            M[j][i] = (v[i] >> j) & 1
            
    b = [(v[8] >> j) & 1 for j in range(8)]
    
    # Gaussian elimination over GF(2)
    A = [row[:] + [b[i]] for i, row in enumerate(M)]
    for col in range(8):
        pivot = -1
        for row in range(col, 8):
            if A[row][col] == 1:
                pivot = row
                break
        if pivot == -1:
            continue
        A[col], A[pivot] = A[pivot], A[col]
        for row in range(8):
            if row != col and A[row][col] == 1:
                for k in range(col, 9):
                    A[row][k] ^= A[col][k]
                    
    c = [A[i][8] for i in range(8)]
    
    # Construct m_3(x)
    m3_poly = 0
    for i in range(8):
        if c[i]:
            m3_poly |= (1 << i)
    m3_poly |= (1 << 8)
    
    # h(x) = (x+1)m_3(x)
    def poly_mul(x, y):
        res = 0
        while y:
            if y & 1:
                res ^= x
            y >>= 1
            x <<= 1
        return res
        
    h_poly = poly_mul(0b11, m3_poly)
    
    # Generate codewords
    def poly_mod(p):
        # Reduce modulo x^17 - 1
        max_bit = p.bit_length()
        for i in range(max_bit - 1, 16, -1):
            if (p >> i) & 1:
                p ^= (1 << (i - 17))
        return p & ((1 << 17) - 1)

    words = set()
    for a in range(256):
        c = poly_mod(poly_mul(a, h_poly))
        words.add(c)
        
    return list(words)
